# Compare actual frozen replay checkpoints without substituting an event engine.
replay_consistency<-function(event_log,original_checkpoints,replayed_checkpoints,snapshot_manifest,replay_contract,context=NULL){
 events<-.vr_rows(event_log,'event_log');oo<-.vs_index(original_checkpoints,'checkpoint_id','original_checkpoints');originals<-oo$rows;oi<-oo$index;rr<-.vs_index(replayed_checkpoints,'checkpoint_id','replayed_checkpoints');replays<-rr$rows;ri<-rr$index;ss<-.vs_index(snapshot_manifest,'snapshot_id','snapshot_manifest');snapshots<-ss$rows;si<-ss$index;cfg<-.ex_object(replay_contract,'replay_contract');for(k in c('contract_id','version','reference')).vb_string(cfg[[k]],k);expected_contract<-list(ordering='KNOWN_AT_SEQUENCE_EVENT_ID',idempotency='FIRST_IDENTICAL_DELIVERY',corrections='APPEND_REVISION');if(any(vapply(names(expected_contract),function(k)!identical(cfg[[k]],expected_contract[[k]]),logical(1)))).cr_error('REPLAY_CONTRACT','Explicit stable ordering, identical idempotency and append-revision required');required<-.ex_ids(cfg$required_checkpoint_ids,'required_checkpoint_ids');atol<-.vb_number(cfg$absolute_tolerance,'absolute_tolerance',0);rtol<-.vb_number(cfg$relative_tolerance,'relative_tolerance',0);violations<-findings<-list();issue<-function(code,unit,detail)violations[[length(violations)+1]]<<-list(code=code,unit_id=unit,detail=detail);event_index<-idempotency<-list();duplicates<-0
 for(e in events){eid<-.vb_string(e$event_id,'event_id');key<-.vb_string(e$idempotency_key,'idempotency_key');occurred<-.cr_data_date(e$occurred_at,'event occurred_at');known<-.cr_data_date(e$known_at,'event known_at');sequence<-.vb_number(e$sequence,'event sequence',0);if(sequence!=floor(sequence)).cr_error('REPLAY_SEQUENCE','Nonnegative integer sequence required');if(known<occurred).cr_error('REPLAY_DATE','Occurrence must precede event knowledge');.ex_object(e$payload,'event payload');if(!identical(e$payload_hash,.cr_hash(e$payload)))issue('EVENT_PAYLOAD_HASH',eid,'Payload hash differs from actual immutable payload');digest<-.cr_hash(e);if(!is.null(event_index[[eid]])&&!identical(digest,.cr_hash(event_index[[eid]]))).cr_error('REPLAY_EVENT_CONFLICT','Repeated event ID differs in immutable content');if(!is.null(idempotency[[key]])){if(!identical(digest,.cr_hash(idempotency[[key]]))).cr_error('REPLAY_IDEMPOTENCY_CONFLICT','Idempotency key can only repeat identical event');duplicates<-duplicates+1}else idempotency[[key]]<-e;event_index[[eid]]<-e};ordered<-unname(idempotency);if(length(ordered))ordered<-ordered[order(vapply(ordered,function(e)e$known_at,character(1)),vapply(ordered,function(e)e$sequence,numeric(1)),vapply(ordered,function(e)e$event_id,character(1)))];position<-setNames(seq_along(ordered),vapply(ordered,function(e)e$event_id,character(1)));for(e in ordered){revision<-e$revision_of;if(!is.null(revision)&&(is.null(event_index[[revision]])||position[[revision]]>=position[[e$event_id]])).cr_error('REPLAY_REVISION','Revision must append after existing earlier-known event')}
 for(s in snapshots){if(!s$kind%in%c('MODEL','CALIBRATION','POLICY','SOURCE')).cr_error('REPLAY_SNAPSHOT','Explicit MODEL/CALIBRATION/POLICY/SOURCE snapshot required');.vs_hashes(list(snapshot=s$content_hash),'snapshot hash');.cr_data_date(s$known_at,'snapshot known_at');start<-.cr_data_date(s$effective_from,'snapshot effective_from');if(!is.null(s$effective_until)&&.cr_data_date(s$effective_until,'snapshot effective_until')<=start).cr_error('REPLAY_SNAPSHOT','Nonempty snapshot effective interval required')};log_hash<-.cr_hash(events)
 state_difference<-function(a,b,path=''){paths<-character();maximum<-0;isnumber<-function(v)is.numeric(v)&&length(v)==1&&is.null(dim(v));if(isnumber(a)&&isnumber(b)){maximum<-abs(a-b);if(!is.finite(maximum)).cr_error('REPLAY_NUMERICAL','State difference exceeds finite range');if(maximum>atol+rtol*abs(a))paths<-c(paths,path)}else if(.cr_object(a)&&.cr_object(b)){if(!setequal(names(a),names(b)))paths<-c(paths,paste0(path,'/<keys>'));for(k in sort(intersect(names(a),names(b)))){r<-state_difference(a[[k]],b[[k]],paste0(path,'/',k));paths<-c(paths,r$paths);maximum<-max(maximum,r$maximum)}}else if(is.list(a)&&is.null(names(a))&&is.list(b)&&is.null(names(b))){if(length(a)!=length(b))paths<-c(paths,paste0(path,'/<length>'));for(i in seq_len(min(length(a),length(b)))){r<-state_difference(a[[i]],b[[i]],paste0(path,'/',i-1));paths<-c(paths,r$paths);maximum<-max(maximum,r$maximum)}}else if(!identical(.cr_hash(a),.cr_hash(b)))paths<-c(paths,path);list(paths=paths,maximum=maximum)}
 for(cid in required){if(is.null(oi[[cid]]))issue('MISSING_ORIGINAL_CHECKPOINT',cid,'Required frozen original absent');if(is.null(ri[[cid]]))issue('MISSING_REPLAY_CHECKPOINT',cid,'Required actual replay output absent')};for(cid in sort(union(names(oi),names(ri)))){if(is.null(oi[[cid]])||is.null(ri[[cid]])){if(!cid%in%required)issue('UNPAIRED_CHECKPOINT',cid,'Original and replay checkpoint sets differ');next};original<-oi[[cid]];replay<-ri[[cid]];before<-length(violations);asof<-.cr_data_date(original$as_of,'checkpoint as_of');known<-.cr_data_date(original$known_at,'checkpoint known_at');if(known<asof).cr_error('REPLAY_CHECKPOINT_DATE','Knowledge cutoff precedes state as-of');eligible<-Filter(function(e).cr_data_date(e$known_at,'event known')<=known&&.cr_data_date(e$occurred_at,'event occurred')<=asof,ordered);expected_ids<-vapply(eligible,function(e)e$event_id,character(1));hashes<-.vs_hashes(original$snapshot_hashes,'checkpoint snapshot_hashes');kinds<-character();for(sid in names(hashes)){s<-si[[sid]];digest<-hashes[[sid]];if(is.null(s)||!identical(s$content_hash,digest)){issue('SNAPSHOT_BINDING_MISMATCH',cid,paste0(sid,' missing or different content hash'));next};kinds<-union(kinds,s$kind);if(.cr_data_date(s$known_at,'snapshot known')>known||.cr_data_date(s$effective_from,'snapshot effective')>asof||!is.null(s$effective_until)&&asof>=.cr_data_date(s$effective_until,'snapshot until'))issue('SNAPSHOT_NOT_HISTORICALLY_APPLICABLE',cid,paste0(sid,' unavailable or outside its effective interval'))};if(!setequal(kinds,c('MODEL','CALIBRATION','POLICY','SOURCE')))issue('MISSING_SNAPSHOT_KIND',cid,'Original must bind model, calibration, policy and source snapshots')
 for(role in c('original','replay')){cp<-if(role=='original')original else replay;.ex_object(cp$state,'checkpoint state');.cr_hash(cp$state);applied<-cp$applied_event_ids;if(is.list(applied)&&is.null(names(applied)))applied<-as.character(unlist(applied,use.names=FALSE));if(!is.character(applied)||anyNA(applied)).cr_error('REPLAY_APPLIED_EVENTS','Applied events must be ordered ID array');if(!identical(applied,expected_ids))issue('EVENT_ORDER_OR_IDEMPOTENCY_MISMATCH',cid,paste0(role,' applied events differ from the eligible unique ordered log'));if(!identical(cp$event_log_hash,log_hash))issue('EVENT_LOG_BINDING_MISMATCH',cid,paste0(role,' does not bind the exact immutable delivery log'))};if(!identical(replay$mode,'REPLAY'))issue('COUNTERFACTUAL_NOT_REPLAY',cid,'Recomputation under changed methods is not historical replay');if(any(vapply(c('as_of','known_at'),function(k)!identical(replay[[k]],original[[k]]),logical(1))))issue('CHECKPOINT_CUTOFF_MISMATCH',cid,'Replay uses different historical observation/knowledge cutoffs');replay_hashes<-.vs_hashes(replay$snapshot_hashes,'replay snapshot_hashes');if(!identical(.cr_hash(replay_hashes),.cr_hash(hashes)))issue('REPLAY_SNAPSHOT_CHANGED',cid,'Replay changed model, calibration, policy or source snapshots');diff<-state_difference(original$state,replay$state);if(length(diff$paths))issue('CHECKPOINT_STATE_MISMATCH',cid,paste0('State differs at ',paste(diff$paths,collapse=',')));findings[[length(findings)+1]]<-list(checkpoint_id=cid,status=if(length(violations)==before)'PASS'else'BLOCKED',expected_applied_event_ids=as.list(expected_ids),known_revision_count=sum(vapply(eligible,function(e)!is.null(e$revision_of),logical(1))),differing_state_paths=as.list(diff$paths),maximum_absolute_numeric_difference=diff$maximum,original_state_hash=.cr_hash(original$state),replay_state_hash=.cr_hash(replay$state))}
 payload<-list(contract=cfg,applicability='APPLICABLE',checkpoint_findings=findings,event_log_hash=log_hash,snapshot_manifest_hash=.cr_hash(snapshots),metrics=list(deliveries=length(events),unique_events=length(ordered),duplicate_identical_deliveries=duplicates,required_checkpoints=length(required),compared_checkpoints=length(findings)),event_execution_performed=FALSE,original_decisions_modified=FALSE,comparison_scope='SUPPLIED_ACTUAL_REPLAY_VERSUS_FROZEN_ORIGINAL');.vs_finish('replay_consistency',payload,violations,list(event_log=events,original_checkpoints=originals,replayed_checkpoints=replays,snapshot_manifest=snapshots,replay_contract=cfg),context)
}
